import { 新状态, handleCommand, 净化镜像, 总杯数, 毒池区间, type StatData } from '../../脚本/对局/core';

/** 楼层绑定：从当前楼层起向下找最近一次对局快照（状态+序列同楼写入）。
 * 回溯到旧楼层时只会读到那条时间线自己的状态，不会再拿到聊天里"最新"的对局信息。 */
function 读取(): StatData {
  try {
    const 当前 = getCurrentMessageId();
    const 最早 = Math.max(0, 当前 - 16);
    for (let mid = 当前; mid >= 最早; mid--) {
      const vars = getVariables({ type: 'message', message_id: mid }) || {};
      const 镜像 = vars.酒鬼对局状态;
      if (镜像 && _.has(镜像, '对局')) {
      const base = JSON.parse(JSON.stringify(镜像)) as StatData;
      base.对局.$序列 = (vars.酒鬼对局序列 as StatData['对局']['$序列']) ?? [];
      base.对局.$透视图 = (vars.酒鬼对局透视 as StatData['对局']['$透视图']) ?? null;
      base.对局.$她透视 = (vars.酒鬼对局她透视 as StatData['对局']['$她透视']) ?? [];
      base.对局.$达令劝她次数 = (vars.酒鬼对局劝怨 as number) ?? 0;

      return 净化镜像(base);
      }
    }
  } catch {
    /* 回退 */
  }
  return 新状态();
}

function 事实块(stat: StatData, 描述: string): string {
  const 对局 = stat.对局;
  const 道具 = (side: '玩家' | '梵·醺儿') =>
    ['解酒药', '透视酒杯', '强行换杯', '啤酒', '薄荷', '毒药', '红冰'].map(key => `${key}x${对局.道具背包[side][key]}`).join(' ');
  const 已揭晓 = 对局.已揭晓.map(x => `第${x.杯号}杯（${x.毒性}·${x.饮者}）`).join('，') || '无';
  const 池 = 毒池区间(stat);
  // 轮数行只记本轮开局基准（上一轮结束后的桌面），避免与本次行动后的状态混淆
  const 本轮结果 = 对局.状态 === '对局中'
    ? `${描述}；现在桌上剩${对局.剩余杯数}杯，毒池可能在 ${池[0]}~${池[1]} 杯`
    : 描述;
  return [
    `行动方：${对局.行动方}${对局.行动方 === '梵·醺儿'
      ? 对局.她的阶段 === '道具'
        ? '（道具阶段：她的道具动作已定，本轮结果只含这一步，不要提前写她喝酒）'
        : 对局.她的阶段 === '劝酒'
          ? `（劝酒中：她把第${对局.她劝的杯号}杯递到达令唇边，等达令回应——喝下或用强行换杯换掉后再喝，不得替达令选择）`
          : '（喝酒阶段）'
      : ''}`,
    `轮数：第${对局.轮数}轮，本轮开始时新摆${总杯数}杯（毒酒${对局.本轮开局毒数}）`,
    `生命：达令${对局.玩家生命}，梵·醺儿${对局.梵醺儿生命}`,
    `醉意：达令${对局.玩家醉意}/${对局.玩家醉意上限 ?? 6}，梵·醺儿${对局.梵醺儿醉意}/${对局.梵醺儿醉意上限 ?? 6}（超过各自上限即醉倒判负）`,
    `已喝杯数：达令${对局.已喝杯数}杯（本轮${对局.已劝酒 ? '已劝过酒' : '未劝酒，喝过一杯后可劝一次'}）`,
    `啤酒杯：${对局.啤酒杯?.length ? 对局.啤酒杯.map(c => `第${c}杯`).join('、') + '（桌上公开，谁喝都是醉意+2、绝对安全）' : '无'}`,
    `冰杯：${对局.冰杯?.length ? 对局.冰杯.map(c => `第${c}杯`).join('、') + '（桌上公开，这杯若是毒酒，喝下额外多扣一点生命；若是其他酒，喝下不涨醉意）' : '无'}`,
    `已揭晓：${已揭晓}`,
    `道具·达令：${道具('玩家')}`,
    `道具·梵·醺儿：${道具('梵·醺儿')}`,
    `上轮结果：${对局.上轮结果 || '无'}`,
    `本轮结果：${本轮结果 || '无变化'}`,
    `灵魂占有度：${stat.灵魂.占有度}%`,
  ].join('\n');
}

export async function 发送指令(指令: string): Promise<void> {
  console.info(`[对局引擎] 收到指令「${指令}」`);
  const 之前 = 读取();
  const { state, changed, valid, 描述 } = handleCommand(之前, 指令);
  if (!valid) return;
  console.info(`[对局引擎] 指令「${指令}」`, changed ? '已生效' : '无变化');
  try {
    await waitGlobalInitialized('Mvu');
    const 序列 = state.对局.$序列;
    const 干净 = { ...state };
    for (const key of ['$序列', '$抵消', '$透视图', '$她透视', '$达令劝她次数'] as const) delete 干净.对局[key];
    // 最近一次行动的落账：桌面日志与事实块共用这段描述，避免界面只显示滞后的上轮结果
    干净.对局.本轮结果 = 描述;
    // 只有"这一指令把对局打完"才打结算标记，结算面板只认它（结算状态下普通指令的快照不再复发面板）
    const 刚结束 = changed && 之前.对局.状态 !== state.对局.状态
      && (state.对局.状态 === '结算' || state.对局.状态 === '终局');
    const 正文 = `${指令}\n\n<对局状态>\n${事实块(干净 as StatData, 描述)}\n</对局状态>`;
    await createChatMessages([{ role: 'user', message: 正文, data: { stat_data: 干净 } }]);
    const id = getLastMessageId();
    const mvu = Mvu.getMvuData({ type: 'message', message_id: id });
    (mvu as Record<string, unknown>).stat_data = 干净;
    await Mvu.replaceMvuData(mvu, { type: 'message', message_id: id });
    // 快照只绑在新楼层上，不再写聊天级变量；接受命运后打标记，终局画面不再重复出现
    // 结算标记记录发生楼层号：面板只准出现在"该楼层+1"（叙述结局的那条回复），
    // 与酒馆是否向前复制楼层变量无关
    const 楼层变量: Record<string, unknown> = {
      酒鬼对局状态: 干净,
      酒鬼对局序列: 序列,
      酒鬼对局透视: state.对局.$透视图,
      酒鬼对局她透视: state.对局.$她透视,
      酒鬼对局劝怨: state.对局.$达令劝她次数,
      酒鬼对局结算: 刚结束,
      酒鬼对局结算楼层: 刚结束 ? id : -1,
    };
    if (指令.trim() === '我接受命运') 楼层变量.酒鬼对局终局已接受 = true;
    await insertOrAssignVariables(楼层变量, { type: 'message', message_id: id });
    console.info('[对局引擎] 状态已写入楼层', id);
    await triggerSlash('/trigger');
  } catch (error) {
    console.error('[对局引擎] 指令失败：', error);
    toastr.error('对局指令发送失败，请查看控制台');
  }
}
