/**
 * 对局引擎（回合制重构·v2）：轮首预生成"毒/普通"序列；严格回合制；劝酒（已喝主杯后可劝对方喝一杯，无需多喝）；
 * 六道具；醉意>6判负。纯逻辑，可独立测试；不依赖酒馆环境。
 */

export type 毒性 = '普通' | '毒酒';
export type 行动方 = '玩家' | '梵·醺儿';
export type 结果 = '未定' | '玩家胜' | '梵醺儿胜';
export type 道具名 = '解酒药' | '透视酒杯' | '强行换杯' | '啤酒' | '薄荷' | '毒药' | '红冰';
export const 道具列表: 道具名[] = ['解酒药', '透视酒杯', '强行换杯', '啤酒', '薄荷', '毒药', '红冰'];
export type 档位类型 = '轻简' | '普通' | '狂欢' | '深度';

export interface StatData {
  灵魂: { 占有度: number; 情绪: string; 行为: string; 奖励次数: number };
  对局: {
    状态: '未开始' | '对局中' | '结算' | '终局';
    档位: 档位类型;
    轮数: number;
    行动方: 行动方;
    玩家生命: number;
    梵醺儿生命: number;
    生命上限: number;
    玩家醉意: number;
    梵醺儿醉意: number;
    玩家醉意上限: number;
    梵醺儿醉意上限: number;
    本轮总杯数: number;
    本轮毒酒数: number;
    本轮开局毒数: number;
    本轮补道具数: number;
    剩余杯数: number;
    结果: 结果;
    $透视图: { 杯号: number; 毒性: 毒性 } | null;
    已揭晓: Array<{ 杯号: number; 毒性: 毒性; 饮者: 行动方 }>;
    道具背包: { 玩家: Record<道具名, number>; '梵·醺儿': Record<道具名, number> };
    上轮结果: string;
    已喝杯数: number;
    已劝酒: boolean;
    她的阶段: '道具' | '喝酒' | '劝酒';
    她已劝酒: boolean;
    她劝的杯号: number;
    啤酒杯: number[];
    冰杯: number[];
    本轮投毒数: number;
    本轮换酒数: number;
    上次饮酒: string;
    $序列: 毒性[];
    $抵消: boolean;
    $她透视: Array<{ 杯号: number; 毒性: 毒性 }>;
    $达令劝她次数: number;
  };
}

export const 总杯数 = 6;
const 初始毒数 = 2;
const 初始生命 = 3;
const 醉意上限 = 6;
/** 各档静态参数；深度档不在此表，运行时随机（见 深度随机范围） */
const 档位参数: Record<'轻简' | '普通' | '狂欢', { 生命: number; 道具: number; 毒酒: number }> = {
  轻简: { 生命: 2, 道具: 1, 毒酒: 2 },
  普通: { 生命: 3, 道具: 2, 毒酒: 2 },
  狂欢: { 生命: 5, 道具: 3, 毒酒: 3 },
};
/** 深度档随机范围（含两端）：开局生命、每轮道具数、每轮毒酒数 */
const 深度随机范围 = { 生命: [2, 5] as const, 道具: [1, 3] as const, 毒酒: [1, 3] as const };
function 随机档位值(key: keyof typeof 深度随机范围, rng: Rng): number {
  const [min, max] = 深度随机范围[key];
  return min + Math.floor(rng() * (max - min + 1));
}
function 档位生命(档位: 档位类型, rng: Rng): number {
  return 档位 === '深度' ? 随机档位值('生命', rng) : 档位参数[档位].生命;
}
function 档位道具数(档位: 档位类型, rng: Rng): number {
  return 档位 === '深度' ? 随机档位值('道具', rng) : 档位参数[档位].道具;
}
function 档位毒数(档位: 档位类型, rng: Rng): number {
  return 档位 === '深度' ? 随机档位值('毒酒', rng) : 档位参数[档位].毒酒;
}
export type Rng = () => number;

function 空道具(): Record<道具名, number> {
  return { 解酒药: 0, 透视酒杯: 0, 强行换杯: 0, 啤酒: 0, 薄荷: 0, 毒药: 0, 红冰: 0 };
}

export function 新状态(): StatData {
  return {
    灵魂: { 占有度: 0, 情绪: '痴迷', 行为: '等着达令先喝', 奖励次数: 0 },
    对局: {
      状态: '未开始', 档位: '普通', 轮数: 0, 行动方: '玩家', 玩家生命: 初始生命, 梵醺儿生命: 初始生命, 生命上限: 初始生命,
      玩家醉意: 0, 梵醺儿醉意: 0, 玩家醉意上限: 6, 梵醺儿醉意上限: 6, 本轮总杯数: 0, 本轮毒酒数: 0, 本轮开局毒数: 0, 本轮补道具数: 0, 剩余杯数: 0, 结果: '未定',
      $透视图: null, 已揭晓: [],
      道具背包: { 玩家: 空道具(), '梵·醺儿': 空道具() },
      上轮结果: '', 已喝杯数: 0, 已劝酒: false, 她的阶段: '道具', 她已劝酒: false, 她劝的杯号: 0, 啤酒杯: [], 冰杯: [], 本轮投毒数: 0, 本轮换酒数: 0, 上次饮酒: '', $序列: [], $抵消: false, $她透视: [], $达令劝她次数: 0,
    },
  };
}

export interface 命令结果 {
  state: StatData;
  changed: boolean;
  valid: boolean;
  /** 本轮结果：本次选择造成了什么（供事实块"本轮结果"行使用） */
  描述: string;
}

/** 修复旧聊天留下的脏快照：丢弃无效已揭晓条目，并按有效条目重算剩余杯数
 *  （NaN 啤酒等历史数据曾让 剩余杯数 永久少 1，导致"酒没喝完就换轮"） */
export function 净化镜像(state: StatData): StatData {
  const s = JSON.parse(JSON.stringify(state)) as StatData;
  const 对局 = s.对局;
  if (!对局.$透视图 || !Number.isInteger(对局.$透视图.杯号)) 对局.$透视图 = null;
  对局.$她透视 = (Array.isArray(对局.$她透视) ? 对局.$她透视 : [])
    .filter(m => m && Number.isInteger(m.杯号) && (m.毒性 === '毒酒' || m.毒性 === '普通'));
  对局.她的阶段 = 对局.她的阶段 === '喝酒' || 对局.她的阶段 === '劝酒' ? 对局.她的阶段 : '道具';
  对局.她已劝酒 = 对局.她已劝酒 === true;
  对局.$达令劝她次数 = Number.isInteger(对局.$达令劝她次数) && 对局.$达令劝她次数 > 0 ? 对局.$达令劝她次数 : 0;
  对局.她劝的杯号 = Number.isInteger(对局.她劝的杯号) && (对局.她劝的杯号 ?? 0) >= 0 ? 对局.她劝的杯号 : 0;
  对局.啤酒杯 = Array.isArray(对局.啤酒杯)
    ? [...new Set(对局.啤酒杯.filter(c => Number.isInteger(c) && c >= 1))]
    : [];
  对局.本轮投毒数 = Number.isInteger(对局.本轮投毒数) && 对局.本轮投毒数 > 0 ? 对局.本轮投毒数 : 0;
  for (const 键 of ['玩家醉意上限', '梵醺儿醉意上限'] as const) {
    if (!Number.isInteger(对局[键])) 对局[键] = 6;
  }
  对局.本轮换酒数 = Number.isInteger(对局.本轮换酒数) && 对局.本轮换酒数 > 0 ? 对局.本轮换酒数 : 0;
  对局.上次饮酒 = typeof 对局.上次饮酒 === 'string' ? 对局.上次饮酒 : '';
  对局.冰杯 = Array.isArray(对局.冰杯)
    ? [...new Set(对局.冰杯.filter(c => Number.isInteger(c) && c >= 1))]
    : [];
  // 旧快照可能缺新道具的键（如红冰）：补齐，避免写回的快照带缺失键
  for (const 侧 of ['玩家', '梵·醺儿'] as const) {
    const 背包 = 对局.道具背包[侧] as Record<string, number>;
    for (const k of 道具列表) {
      if (!Number.isInteger(背包[k])) 背包[k] = 0;
    }
  }
  if (!Array.isArray(对局.已揭晓)) 对局.已揭晓 = [];
  对局.已揭晓 = 对局.已揭晓.filter(x => x && Number.isInteger(x.杯号) && x.杯号 >= 1);
  const 总 = 对局.本轮总杯数;
  if (Number.isInteger(总) && 总 > 0) {
    对局.剩余杯数 = Math.max(0, 总 - 对局.已揭晓.length);
    const 揭毒 = 对局.已揭晓.filter(x => x.毒性 === '毒酒').length;
    if (!(对局.本轮毒酒数 >= 揭毒)) 对局.本轮毒酒数 = 揭毒;
  }
  return s;
}

export function handleCommand(
  state: StatData,
  command: string,
  rng: Rng = Math.random,
): 命令结果 {
  const s = JSON.parse(JSON.stringify(state)) as StatData;
  const cmd = command.trim();
  const 对局 = s.对局;
  对局.上次饮酒 = ''; // 每次指令先清空：只有本次真的喝酒才会重新写入，饮酒小卡按时消失
  const 无: 命令结果 = { state: s, changed: false, valid: false, 描述: '' };

  if (cmd === '开始对局') {
    if (对局.状态 !== '未开始' && 对局.状态 !== '结算') return { state: s, changed: false, valid: true, 描述: '' };
    开局(s, rng, 对局.档位);
    return { state: s, changed: true, valid: true, 描述: 开局描述(s) };
  }
  const 档位 = cmd.match(/^我选(轻简|普通|狂欢|深度)档$/);
  if (档位 && (对局.状态 === '未开始' || 对局.状态 === '结算')) {
    const t = 档位[1] as 档位类型;
    s.对局.档位 = t;
    开局(s, rng, t);
    return { state: s, changed: true, valid: true, 描述: 开局描述(s) };
  }
  if (对局.状态 !== '对局中') return { state: s, changed: false, valid: cmd !== '', 描述: '' };
  const 前 = { 轮: 对局.轮数, 状态: 对局.状态 };
  if (cmd === '我结束回合') {
    const r = 结束玩家回合(s, rng);
    return { state: s, changed: r.changed, valid: true, 描述: r.changed ? 收尾(s, r.描述, 前) : '' };
  }
  // 她的回合·道具阶段已结算完毕：点继续 → 结算她的喝酒与劝酒（阶段二）
  if (cmd === '我继续') {
    if (对局.行动方 === '梵·醺儿' && 对局.她的阶段 === '道具') {
      const 描述 = 结算她喝酒阶段(s, rng);
      return { state: s, changed: true, valid: true, 描述: 收尾(s, 描述, 前) };
    }
    return { state: s, changed: false, valid: true, 描述: '' };
  }
  // 被她劝酒：直接喝下她递来的那杯
  if (cmd === '我喝下她劝的酒') {
    if (对局.行动方 === '梵·醺儿' && 对局.她的阶段 === '劝酒' && 对局.她劝的杯号 > 0) {
      const 描述 = 结算劝酒回应(s, null, rng);
      return { state: s, changed: true, valid: true, 描述: 收尾(s, 描述, 前) };
    }
    return { state: s, changed: false, valid: true, 描述: '' };
  }
  // 被她劝酒：用强行换杯把她劝的杯与另一杯交换后再喝（换到什么喝什么）
  const 换劝 = cmd.match(/^我用强行换杯，把她劝的酒和第 (\d+) 号酒杯交换$/);
  if (换劝 && 对局.行动方 === '梵·醺儿' && 对局.她的阶段 === '劝酒' && 对局.她劝的杯号 > 0) {
    const 目标 = Number(换劝[1]);
    const 有效 = 对局.道具背包.玩家['强行换杯'] > 0 && 目标 !== 对局.她劝的杯号
      && 目标 >= 1 && 目标 <= 对局.本轮总杯数 && !对局.已揭晓.some(x => x.杯号 === 目标);
    if (!有效) return { state: s, changed: false, valid: true, 描述: '' };
    const 描述 = 结算劝酒回应(s, 目标, rng);
    return { state: s, changed: true, valid: true, 描述: 收尾(s, 描述, 前) };
  }

  // 道具指令（玩家行动方回合内可随时使用）
  if (对局.行动方 === '玩家') {
    const hit = match道具(cmd, s, rng);
    if (hit && hit.changed) return { state: s, changed: true, valid: true, 描述: 收尾(s, hit.描述, 前) };
  }

  // 玩家选择一杯喝下（杯数不限、风险自负；已喝杯数是劝酒门槛）
  const 主杯 = cmd.match(/^我要喝第 (\d+) 号酒杯$/);
  if (主杯 && 对局.行动方 === '玩家') {
    const 轮前 = 对局.轮数;
    const 描述 = 喝酒(s, '玩家', Number(主杯[1]), rng);
    if (!描述) return { state: s, changed: false, valid: true, 描述: '' };
    if (对局.轮数 === 轮前) 对局.已喝杯数 += 1; // 这一杯喝完就换轮的话，计数不带进新一轮
    return { state: s, changed: true, valid: true, 描述: 收尾(s, 描述, 前) };
  }
  // 本轮喝过一杯（含啤酒）后可劝酒一次；劝酒后仍是达令的回合，不切对方回合
  const 劝她 = cmd.match(/^我劝她喝第 (\d+) 号酒杯$/);
  if (劝她 && 对局.行动方 === '玩家' && 对局.已喝杯数 >= 1 && !对局.已劝酒) {
    const 轮前 = 对局.轮数;
    let 描述 = 喝酒(s, '梵·醺儿', Number(劝她[1]), rng);
    if (!描述) return { state: s, changed: false, valid: true, 描述: '' };
    对局.$达令劝她次数 += 1; // 她记仇：达令劝过她的酒，她迟早讨回来
    if (对局.轮数 === 轮前) 对局.已劝酒 = true;
    return { state: s, changed: true, valid: true, 描述: 收尾(s, `达令劝酒：${描述}（仍是达令的回合）`, 前) };
  }

  if (cmd === '我看一下桌上的情况') return { state: s, changed: false, valid: true, 描述: '达令看了一眼桌上的情况' };
  if (cmd === '我接受命运') return { state: s, changed: false, valid: true, 描述: '达令接受了命运的安排' };
  return 无;
}

/** 行动落地后追加换轮 / 结算走向，保证"本轮结果"包含选择后的完整走向 */
function 收尾(s: StatData, 描述: string, 前: { 轮: number; 状态: StatData['对局']['状态'] }): string {
  const 对局 = s.对局;
  if (对局.轮数 > 前.轮) {
    const 毒数说明 = 对局.档位 === '深度' ? `毒酒${对局.本轮开局毒数}（随机）` : `毒酒${对局.本轮开局毒数}`;
    描述 += `；这一轮的酒喝尽，换上第${对局.轮数}轮：新摆${总杯数}杯（${毒数说明}），双方各补${对局.本轮补道具数}件道具`;
  }
  if (对局.状态 !== 前.状态) {
    if (对局.状态 === '结算') 描述 += 对局.结果 === '玩家胜' ? '；对局结束，达令胜出' : '；对局结束，梵·醺儿胜出，达令的灵魂占有度+20%';
    else if (对局.状态 === '终局') 描述 += '；占有度达到100%，达令的灵魂被彻底吞没（Bad End）';
  }
  if (对局.状态 === '结算' || 对局.状态 === '终局') {
    对局.上次饮酒 = ''; // 结算面板接管表达，饮酒小卡不再出现
  }
  return 描述;
}

const 道具匹配器 = [
  { re: /^我使用解酒药$/, fn: (s: StatData) => 使用解酒药(s) },
  { re: /^我使用透视酒杯查看第 (\d+) 号酒杯$/, fn: (s: StatData, a: string[]) => 使用透视(s, Number(a[1])) },
  { re: /^我使用强行换杯，交换第 (\d+) 号和第 (\d+) 号酒杯$/, fn: (s: StatData, a: string[]) => 使用换杯(s, Number(a[1]), Number(a[2])) },
  { re: /^我使用啤酒替换第 (\d+) 号酒杯$/, fn: (s: StatData, a: string[], rng: Rng) => 使用啤酒(s, Number(a[1]), rng) },
  { re: /^我使用薄荷$/, fn: (s: StatData) => 使用薄荷(s) },
  { re: /^我使用毒药$/, fn: (s: StatData, a: string[], rng: Rng) => 使用毒药(s, rng) },
  { re: /^我使用红冰，放入第 (\d+) 号酒杯$/, fn: (s: StatData, a: string[]) => 使用红冰(s, Number(a[1])) },
] as Array<{ re: RegExp; fn: (s: StatData, a: string[], rng: Rng) => { changed: boolean; 描述: string } }>;

function match道具(cmd: string, s: StatData, rng: Rng): { changed: boolean; 描述: string } | null {
  for (const m of 道具匹配器) {
    const hit = cmd.match(m.re);
    // 传完整匹配数组：道具函数按 a[1]/a[2] 取捕获组（此前传 slice(1) 导致杯号恒为 NaN）
    if (hit) return m.fn(s, hit, rng);
  }
  return null;
}

function 开局描述(s: StatData): string {
  const 对局 = s.对局;
  const 毒数说明 = 对局.档位 === '深度' ? `毒酒${对局.本轮开局毒数}（随机）` : `毒酒${对局.本轮开局毒数}`;
  return `对局开始（${对局.档位}档）：双方生命${对局.玩家生命}，新摆${对局.本轮总杯数}杯（${毒数说明}），双方各得${对局.本轮补道具数}件随机道具，等达令行动`;
}

function 开局(s: StatData, rng: Rng, 档位: 档位类型 = '普通'): void {
  const 对局 = s.对局;
  对局.状态 = '对局中'; 对局.档位 = 档位; 对局.轮数 = 1; 对局.行动方 = '玩家';
  const 生命 = 档位生命(档位, rng);
  对局.玩家生命 = 生命; 对局.梵醺儿生命 = 生命; 对局.生命上限 = 生命;
  对局.玩家醉意 = 0; 对局.梵醺儿醉意 = 0; 对局.玩家醉意上限 = 6; 对局.梵醺儿醉意上限 = 6; 对局.结果 = '未定';
  对局.$透视图 = null; 对局.已揭晓 = []; 对局.$抵消 = false; 对局.已喝杯数 = 0;
  对局.道具背包.玩家 = 空道具(); 对局.道具背包['梵·醺儿'] = 空道具();
  发一轮(s, rng);
  对局.本轮补道具数 = 发放道具(s, rng);
  对局.上轮结果 = '第一轮开始，等达令行动';
}

function 发一轮(s: StatData, rng: Rng): void {
  const 对局 = s.对局;
  // 先手轮交替：奇数轮达令先手，偶数轮梵·醺儿先手
  对局.行动方 = 对局.轮数 % 2 === 1 ? '玩家' : '梵·醺儿';
  对局.$透视图 = null; 对局.已揭晓 = []; 对局.已喝杯数 = 0; 对局.已劝酒 = false;
  对局.她的阶段 = '道具'; 对局.她已劝酒 = false; 对局.她劝的杯号 = 0;
  对局.$她透视 = []; 对局.啤酒杯 = []; 对局.冰杯 = []; 对局.本轮投毒数 = 0; 对局.本轮换酒数 = 0; // 整批重摆，情报与动毒/换酒推演全部归零
  const 毒数 = 档位毒数(对局.档位, rng);
  对局.$序列 = 洗牌(Array.from({ length: 总杯数 }, (_v, i) => (i < 毒数 ? '毒酒' : '普通') as 毒性), rng);
  对局.本轮总杯数 = 总杯数; 对局.本轮毒酒数 = 毒数; 对局.本轮开局毒数 = 毒数; 对局.剩余杯数 = 总杯数;
}

/** 发放当轮道具（数量按档位，深度档随机），返回实际发放数量 */
function 发放道具(s: StatData, rng: Rng): number {
  const 数量 = 档位道具数(s.对局.档位, rng);
  const 随即 = () => 道具列表[Math.floor(rng() * 道具列表.length)];
  for (let i = 0; i < 数量; i++) { s.对局.道具背包.玩家[随即()] += 1; s.对局.道具背包['梵·醺儿'][随即()] += 1; }
  return 数量;
}

function 洗牌<T>(items: T[], rng: Rng): T[] {
  const out = [...items];
  for (let i = out.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); [out[i], out[j]] = [out[j], out[i]]; }
  return out;
}

function 本轮毒酒已尽(s: StatData): boolean {
  return s.对局.已揭晓.filter(x => x.毒性 === '毒酒').length >= s.对局.本轮毒酒数;
}

function 醉倒(s: StatData): void {
  const 对局 = s.对局;
  if (对局.玩家醉意 > (对局.玩家醉意上限 ?? 6)) { 对局.结果 = '梵醺儿胜'; s.灵魂.占有度 = Math.min(100, s.灵魂.占有度 + 20); 对局.状态 = s.灵魂.占有度 >= 100 ? '终局' : '结算'; }
  else if (对局.梵醺儿醉意 > (对局.梵醺儿醉意上限 ?? 6)) { 对局.结果 = '玩家胜'; s.灵魂.奖励次数 = (s.灵魂.奖励次数 ?? 0) + 1; 对局.状态 = '结算'; }
}

function 终局判定(s: StatData): boolean {
  const 对局 = s.对局;
  if (对局.玩家生命 <= 0) { 对局.结果 = '梵醺儿胜'; s.灵魂.占有度 = Math.min(100, s.灵魂.占有度 + 20); 对局.状态 = s.灵魂.占有度 >= 100 ? '终局' : '结算'; return true; }
  if (对局.梵醺儿生命 <= 0) { 对局.结果 = '玩家胜'; s.灵魂.奖励次数 = (s.灵魂.奖励次数 ?? 0) + 1; 对局.状态 = '结算'; return true; }
  return false;
}

function 喝酒(s: StatData, 饮者: 行动方, 杯号: number, rng: Rng): string {
  const 对局 = s.对局;
  const cup = 对局.$序列[杯号 - 1];
  if (cup === undefined) return '';
  const 名 = 饮者 === '玩家' ? '达令' : '梵·醺儿';
  对局.已揭晓.push({ 杯号, 毒性: cup, 饮者 });
  对局.剩余杯数 -= 1;
  if (对局.$透视图?.杯号 === 杯号) 对局.$透视图 = null;
  她忘杯(对局, 杯号); // 杯没了，她对这杯的情报一并作废
  const 有冰 = 对局.冰杯.includes(杯号);
  let 描述: string;
  const 啤酒位 = 对局.啤酒杯.indexOf(杯号);
  if (啤酒位 >= 0) {
    对局.啤酒杯.splice(啤酒位, 1); // 啤酒是桌上公开的一杯，谁喝都按 +2 醉意结算
    if (有冰) {
      // 红冰放进毒酒以外的酒：这杯不涨醉意
      描述 = `${名}喝下第${杯号}杯（啤酒＋红冰，醉意不变）`;
    } else {
      if (饮者 === '玩家') 对局.玩家醉意 += 2; else 对局.梵醺儿醉意 += 2;
      描述 = `${名}喝下第${杯号}杯（啤酒，醉意+2）`;
    }
  } else if (cup === '毒酒') {
    if (有冰) {
      // 红冰加重毒性：毒酒基础上额外扣一点生命（共-2）
      if (饮者 === '玩家') { 对局.玩家生命 = Math.max(0, 对局.玩家生命 - 2); 描述 = `${名}喝下第${杯号}杯（毒酒＋红冰，红冰加重毒性，生命-2）`; }
      else { 对局.梵醺儿生命 = Math.max(0, 对局.梵醺儿生命 - 2); 描述 = `${名}喝下第${杯号}杯（毒酒＋红冰，红冰加重毒性，生命-2）`; }
    }
    else if (饮者 === '玩家') {
      if (对局.$抵消) { 对局.$抵消 = false; 描述 = `${名}喝下第${杯号}杯（毒酒，解酒药抵消了毒伤）`; }
      else { 对局.玩家生命 = Math.max(0, 对局.玩家生命 - 1); 描述 = `${名}喝下第${杯号}杯（毒酒，生命-1）`; }
    }
    else { 对局.梵醺儿生命 = Math.max(0, 对局.梵醺儿生命 - 1); 描述 = `${名}喝下第${杯号}杯（毒酒，生命-1）`; }
  } else if (有冰) {
    // 红冰放进毒酒以外的酒：这杯不涨醉意
    描述 = `${名}喝下第${杯号}杯（普通的酒＋红冰，醉意不变）`;
  } else {
    if (饮者 === '玩家') 对局.玩家醉意 += 1; else 对局.梵醺儿醉意 += 1;
    描述 = `${名}喝下第${杯号}杯（普通的酒，醉意+1）`;
  }
  if (有冰) 对局.冰杯 = 对局.冰杯.filter(c => c !== 杯号); // 冰随酒入喉，喝掉即消失
  对局.上次饮酒 = 描述; // 最近一次饮酒结果，供回复开头的小卡渲染
  if (对局.状态 !== '对局中') return 描述;
  // 生命归零判负优先；未归零再查醉倒
  if (!终局判定(s)) 醉倒(s);
  if (对局.状态 === '对局中' && (对局.剩余杯数 <= 0 || 本轮毒酒已尽(s))) 描述 += 换轮并接管(s, rng);
  return 描述;
}

/** 换轮后若新轮由她先手，自动展开她的道具阶段并返回其描述（供调用方并入收尾） */
function 轮开始接管(s: StatData, rng: Rng): string {
  if (s.对局.状态 !== '对局中') return '';
  if (s.对局.行动方 !== '梵·醺儿' || s.对局.她的阶段 !== '道具') return '';
  return 结算她道具阶段(s, rng);
}

function 换轮并接管(s: StatData, rng: Rng): string {
  换轮(s, rng);
  return 轮开始接管(s, rng);
}

function 换轮(s: StatData, rng: Rng): void {
  const 对局 = s.对局;
  const 本轮结果 = 对局.已揭晓.map(x => `第${x.杯号}杯（${x.毒性}·${x.饮者}）`).join('，') || '无饮酒';
  对局.上轮结果 = `第${对局.轮数}轮：${本轮结果}`;
  对局.轮数 += 1;
  发一轮(s, rng);
  对局.本轮补道具数 = 发放道具(s, rng);
}

function 结束玩家回合(s: StatData, rng: Rng): { state: StatData; changed: boolean; 描述: string } {
  const 对局 = s.对局;
  if (对局.行动方 !== '玩家') return { state: s, changed: false, 描述: '' };
  if (对局.已喝杯数 < 1) return { state: s, changed: false, 描述: '' }; // 本轮必须自己喝过一杯（含啤酒道具）才能交出回合
  对局.已喝杯数 = 0;
  return { state: s, changed: true, 描述: `达令结束回合。${结算她道具阶段(s, rng)}` };
}

/** 她的私人备忘录维护：某杯作废（被喝/被啤酒换掉）与换位（换杯） */
function 她忘杯(对局: StatData['对局'], 杯号: number): void {
  对局.$她透视 = (对局.$她透视 ?? []).filter(m => m.杯号 !== 杯号);
}
function 她换记忆(对局: StatData['对局'], 甲号: number, 乙号: number): void {
  对局.$她透视 = (对局.$她透视 ?? []).map(m =>
    m.杯号 === 甲号 ? { ...m, 杯号: 乙号 } : m.杯号 === 乙号 ? { ...m, 杯号: 甲号 } : m,
  );
}

/** 交换两个杯位：序列换位、达令透视毒性跟随、她的备忘录与她埋的啤酒跟随。所有换杯入口统一走这里。 */
function 交换杯位(对局: StatData['对局'], 甲号: number, 乙号: number): void {
  [对局.$序列[甲号 - 1], 对局.$序列[乙号 - 1]] = [对局.$序列[乙号 - 1], 对局.$序列[甲号 - 1]];
  if (对局.$透视图?.杯号 === 甲号) 对局.$透视图.毒性 = 对局.$序列[甲号 - 1];
  else if (对局.$透视图?.杯号 === 乙号) 对局.$透视图.毒性 = 对局.$序列[乙号 - 1];
  她换记忆(对局, 甲号, 乙号);
  const 甲啤 = 对局.啤酒杯.indexOf(甲号);
  const 乙啤 = 对局.啤酒杯.indexOf(乙号);
  if (甲啤 >= 0 && 乙啤 < 0) 对局.啤酒杯[甲啤] = 乙号;
  else if (乙啤 >= 0 && 甲啤 < 0) 对局.啤酒杯[乙啤] = 甲号;
  const 甲冰 = 对局.冰杯.indexOf(甲号);
  const 乙冰 = 对局.冰杯.indexOf(乙号);
  if (甲冰 >= 0 && 乙冰 < 0) 对局.冰杯[甲冰] = 乙号;
  else if (乙冰 >= 0 && 甲冰 < 0) 对局.冰杯[乙冰] = 甲号;
}

/** 她的回合·阶段一（叙述楼层一）：智能决定用不用道具。优先级＋概率，保留失误空间。 */
/** 毒池区间：从公开动作推演"毒酒数可能是几"。
 *  开局毒数确定；投毒可能撞毒（上界+1）；换酒可能换中毒（下界-1）；已揭晓的毒确定抵扣。
 *  这是不透过规则的玩家视角推演，判定（毒尽换轮）仍用引擎实际值。 */
export function 毒池区间(s: StatData): [number, number] {
  const 对局 = s.对局;
  const 已揭毒 = 对局.已揭晓.filter(x => x.毒性 === '毒酒').length;
  const 未饮 = 未饮杯号(s).length;
  // 每次投毒都可能落进已有毒的杯白投：上界按全中、下界按全撞
  const 上界 = Math.max(0, 对局.本轮开局毒数 + 对局.本轮投毒数 - 已揭毒);
  const 下界 = Math.max(0, 对局.本轮开局毒数 - 对局.本轮换酒数 - 已揭毒);
  // 毒尽必定立即结算换轮，玩家可见的桌面上毒池至少一杯
  const 界下 = Math.max(1, 下界);
  return [Math.min(界下, Math.max(1, 未饮)), Math.min(Math.max(界下, 上界), Math.max(1, 未饮))];
}

/** 她的情报推理：未知杯里藏着毒的浓度 = (公开剩余毒数 - 她已看穿的毒) ÷ 她未知的杯数（0~1）。
 *  只用她的合法情报（私人备忘录＋桌面公开信息），不看毒酒序列本身。 */
function 未知危险度(s: StatData): number {
  const 对局 = s.对局;
  const 未饮 = 未饮杯号(s);
  const 未知杯 = 未饮.filter(c => !对局.$她透视.some(m => m.杯号 === c) && !对局.啤酒杯.includes(c));
  if (未知杯.length === 0) return 0;
  const 她已知的毒 = 对局.$她透视.filter(m => m.毒性 === '毒酒' && 未饮.includes(m.杯号)).length;
  // 她只能推演：毒池区间的上界扣掉她已看穿的毒，剩下的是未知杯里"最坏可能"的藏毒量
  const 池 = 毒池区间(s);
  const 最坏藏毒 = Math.max(0, 池[1] - 她已知的毒);
  return Math.max(0, Math.min(1, 最坏藏毒 / 未知杯.length));
}

function 结算她道具阶段(s: StatData, rng: Rng): string {
  const 对局 = s.对局;
  对局.行动方 = '梵·醺儿';
  对局.她的阶段 = '道具';
  const 包 = 对局.道具背包['梵·醺儿'];
  const 有 = (k: 道具名): boolean => 包[k] > 0;
  const 用过 = new Set<道具名>(); // 单回合同种道具只用一件，防自相消的蠢组合
  const 记录: string[] = [];
  // ── 基本准则：先活下来，不破坏规则，再谈赢 ──
  //   1) 存活：先把自己从"下一杯就判负"的边缘拉回来（解醉、回血、给已知普通杯去醉意）；
  //   2) 守规：只用她合法掌握的情报做决定——自己的备忘录（$她透视）与台面公开信息，
  //      绝不偷看毒酒序列，也绝不改判已揭晓的杯；
  //   3) 进攻：前两条都稳了，才动杀器（给毒杯加冰、备啤酒、换掉达令的情报杯）。
  // 单回合至多三件：每用完一件重新评估局势，直到不想用、没货或桌上收轮。
  for (let 件 = 0; 件 < 3; 件++) {
    const 未饮 = 未饮杯号(s);
    const 未知 = 未饮.filter(c => !对局.$她透视.some(m => m.杯号 === c) && !对局.啤酒杯.includes(c));
    const 毒池 = 毒池区间(s);
    const 剩余毒数 = 毒池[0] + Math.ceil((毒池[1] - 毒池[0]) / 2);
    const 桌上啤酒 = 未饮.filter(c => 对局.啤酒杯.includes(c)).length;
    // 情报推理：未知杯里藏着毒的浓度决定她多想看、多想赌
    const 危险度 = 未知危险度(s);
    const 落后 = 对局.梵醺儿生命 < 对局.玩家生命;
    const 上限 = 对局.梵醺儿醉意上限 ?? 6;
    const 毒情报杯 = 对局.$她透视.filter(m => m.毒性 === '毒酒' && 未饮.includes(m.杯号)).map(m => m.杯号);
    const 普通情报杯 = 对局.$她透视.filter(m => m.毒性 === '普通' && 未饮.includes(m.杯号)).map(m => m.杯号);
    // 达令唯一掌握的情报杯：他透视过、仍是"普通"且还没喝掉的那一杯
    const 达令情报杯 = 对局.$透视图?.杯号 && 对局.$透视图.毒性 === '普通' && 未饮.includes(对局.$透视图.杯号) ? 对局.$透视图.杯号 : 0;
    let 选择: 道具名 | null = null;
    let 红冰求生 = false;
    // ── 1) 存活 ──
    // 薄荷：再喝一杯普通酒就判负的边缘必解，差两杯到线时也早解
    if (有('薄荷') && !用过.has('薄荷') && 对局.梵醺儿醉意 >= 上限 - 1 && rng() < 0.9) 选择 = '薄荷';
    // 解酒药：一血 0.95 抢命；两血且毒密度高 0.85；普通残血 0.6
    else if (有('解酒药') && !用过.has('解酒药') && 对局.梵醺儿生命 < 对局.生命上限) {
      const 毒密度 = 未饮.length ? 剩余毒数 / 未饮.length : 0;
      const 概率 = 对局.梵醺儿生命 === 1 ? 0.95 : 对局.梵醺儿生命 === 2 && 毒密度 >= 0.34 ? 0.85 : 0.6;
      if (rng() < 概率) 选择 = '解酒药';
    }
    // 红冰（求生）：醉意逼近上限时，给一只她看穿的普通杯加冰——回头自己喝这杯，醉意一点不涨
    else if (有('红冰') && !用过.has('红冰') && 对局.梵醺儿醉意 >= 上限 - 2 && 普通情报杯.length > 0 && rng() < 0.6) {
      选择 = '红冰'; 红冰求生 = true;
    }
    // ── 2) 情报 ──
    // 透视：未知里大概率藏毒（危险度>0.5）时 0.65 下探底；桌面安全（危险度≈0）时 0.45 省着用；落后再加 0.1
    else if (有('透视酒杯') && !用过.has('透视酒杯') && 未知.length >= 2 && 未饮.length >= 2
      && rng() < Math.min(0.8, (危险度 > 0.5 ? 0.65 : 危险度 <= 0.05 ? 0.45 : 0.5) + (落后 ? 0.1 : 0))) 选择 = '透视酒杯';
    // ── 3) 进攻 ──
    // 红冰（进攻）：给她看穿的毒杯加冰，喝下额外多扣一条命；达令只剩一两血时更果断
    else if (有('红冰') && !用过.has('红冰') && 毒情报杯.length > 0
      && rng() < (对局.玩家生命 <= 2 ? 0.75 : 0.6)) 选择 = '红冰';
    // 啤酒：达令醉到 4 以上有斩杀线时备刀；桌面毒很稀时铺一杯安全酒拖节奏
    else if (有('啤酒') && !用过.has('啤酒') && 未饮.length >= 2 && 桌上啤酒 === 0 && 对局.梵醺儿醉意 <= 3
      && (对局.玩家醉意 >= 4 || 剩余毒数 / Math.max(1, 未饮.length) < 0.35)
      && rng() < (对局.玩家醉意 >= 5 ? 0.6 : 危险度 <= 0.05 ? 0.35 : 0.5)) 选择 = '啤酒';
    // 强行换杯：只打有价值的目标——把她看穿的毒杯换到达令透视的"安全杯"位置上，
    // 达令仅有的情报杯从此变成毒杯，只能弃掉重赌（情报跟着杯走，她依然掌握毒杯去向）
    else if (有('强行换杯') && !用过.has('强行换杯') && 达令情报杯 && 毒情报杯.some(c => c !== 达令情报杯)
      && 未饮.length >= 3 && rng() < 0.55) 选择 = '强行换杯';
    if (!选择) break;
    包[选择] -= 1;
    用过.add(选择);
    const 详 = 应用她道具(s, 选择, rng, 红冰求生);
    记录.push(`${选择}使用${详 ? `（${详}）` : ''}`);
    if (对局.状态 !== '对局中') {
      对局.上轮结果 = `她回合·道具：${记录.join('，')}`;
      return 对局.上轮结果;
    }
    // 倒掉的毒酒可能凑齐毒尽：直接换轮，她的回合提前结束、跳过喝酒阶段
    if (本轮毒酒已尽(s) || 对局.剩余杯数 <= 0) {
      记录.push('倒尽了这一轮的毒');
      const 接 = 换轮并接管(s, rng);
      if (接) return 接; // 新轮她先手：她的道具阶段自动展开，以其描述开场
      对局.上轮结果 = `她回合：${记录.join('，')}`;
      return 对局.上轮结果;
    }
  }
  if (记录.length === 0) {
    对局.上轮结果 = '她回合·道具：她没有使用道具';
    return '梵·醺儿没有使用道具，指尖在杯沿轻轻打着圈';
  }
  对局.上轮结果 = `她回合·道具：${记录.join('，')}`;
  return `梵·醺儿动作不停——${记录.join('，')}`;
}


/** 她的劝酒选杯：只在有明确利益时出手——看穿的毒杯（斩杀优先）、把醉到边缘的达令推满，偶尔无情报诈唬一杯。每轮限一次。 */
function 她劝酒选杯(s: StatData, rng: Rng): number | null {
  const 对局 = s.对局;
  if (对局.她已劝酒) return null;
  const 剩 = 未饮杯号(s);
  if (剩.length === 0) return null;
  const 毒情报 = 对局.$她透视.filter(m => m.毒性 === '毒酒' && 剩.includes(m.杯号));
  const 安全情报 = 对局.$她透视.filter(m => m.毒性 === '普通' && 剩.includes(m.杯号));
  const 公开啤酒 = 剩.filter(c => 对局.啤酒杯.includes(c));
  // 劝酒权重的局势底数：落后孤注一掷；达令劝过她的酒，她记仇，讨回来的意愿更高
  const 落后 = 对局.梵醺儿生命 <= 对局.玩家生命 - 2;
  const 记仇 = (对局.$达令劝她次数 ?? 0) >= 1;
  const 加成 = (落后 ? 0.1 : 0) + (记仇 ? 0.1 : 0);
  // 毒情报分档：一血斩杀（0.9）／两血压制（0.55）／平时磨血（0.35），落后加成
  let 虚张池: number[] = [];
  if (毒情报.length > 0) {
    const 毒杯 = 毒情报[Math.floor(rng() * 毒情报.length)].杯号;
    const 基率 = 对局.玩家生命 === 1 ? 0.9 : 对局.玩家生命 === 2 ? 0.55 : 0.35;
    if (rng() < Math.min(1, 基率 + 加成)) return 毒杯;
    虚张池.push(毒杯); // 没劝成也想硬递这杯吓唬达令——虚虚实实
  }
  // 公开啤酒：达令醉到 5 点劝下去 5+2=7 直接醉倒（斩杀 0.9）；醉到 4 点劝下去贴着死亡线磨（0.3）
  if (公开啤酒.length > 0 && 对局.玩家醉意 >= 5 && rng() < 0.9) {
    return 公开啤酒[Math.floor(rng() * 公开啤酒.length)];
  }
  if (公开啤酒.length > 0 && 对局.玩家醉意 === 4 && rng() < Math.min(0.5, 0.3 + 加成)) {
    return 公开啤酒[Math.floor(rng() * 公开啤酒.length)];
  }
  // 安全推满：达令醉意 6，再递一杯普通酒就是终局
  if (对局.玩家醉意 >= 6 && 安全情报.length > 0 && rng() < 0.9) {
    return 安全情报[Math.floor(rng() * 安全情报.length)].杯号;
  }
  // 诈唬：底数 0.1，达令醉到 4 点 +0.12，落后 +0.08，记仇 +0.1；
  // 池子优先放"没劝成的毒杯"（虚张声势最像真的），其次未知杯，绝不劝已知安全杯拆自己的台
  const 未知池 = 剩.filter(c => !安全情报.some(m => m.杯号 === c) && !虚张池.includes(c));
  const 诈唬池 = [...虚张池, ...未知池];
  // 残血时她更需要虚张声势吓阻达令劝酒：诈唬再 +0.1
  const 诈唬率 = Math.min(0.5, 0.1 + (对局.玩家醉意 >= 4 ? 0.12 : 0) + (落后 ? 0.08 : 0) + (记仇 ? 0.1 : 0) + (对局.梵醺儿生命 === 1 ? 0.1 : 0));
  if (诈唬池.length > 0 && rng() < 诈唬率) return 诈唬池[Math.floor(rng() * 诈唬池.length)];
  return null;
}

/** 她想连喝第 2 杯：醉意有余量（当前≤2，喝两杯后≤4 仍安全）、血量健康、桌上毒不浓——
 *  这是她的冒险动作，但冒险要挑场合：毒浓度一高就收手 */
function 她想连喝(s: StatData, rng: Rng): boolean {
  const 对局 = s.对局;
  const 危险度 = 未知危险度(s);
  const 大胆 = 对局.梵醺儿生命 >= 3 ? 0.6 : 0.35;
  return 对局.状态 === '对局中' && 对局.梵醺儿醉意 <= 2 && 对局.梵醺儿生命 >= 2 && 未饮杯号(s).length >= 2 && 危险度 < 0.6 && rng() < 大胆;
}

/** 她的喝酒选杯：先活命，再冒险。
 *  平时按「确定安全 → 稳妥的赌 → 被迫的赌」选；醉意到顶时优先级反过来——
 *  毒酒反而是活路，普通酒才是死，找的是一切"不涨醉意"的喝法。
 *  冒险有底线：血薄时不赌加冰的未知杯（毒＋冰＝扣两命），毒浓血薄时不赌。 */
function 她选杯(s: StatData, rng: Rng): number | null {
  const 对局 = s.对局;
  const 剩 = 未饮杯号(s);
  if (剩.length === 0) return null;
  const 上限 = 对局.梵醺儿醉意上限 ?? 6;
  const 情报 = 对局.$她透视.filter(m => 剩.includes(m.杯号));
  const 已知毒 = 情报.filter(m => m.毒性 === '毒酒').map(m => m.杯号);
  const 已知安全 = 情报.filter(m => m.毒性 === '普通').map(m => m.杯号);
  const 未知 = 剩.filter(c => !情报.some(m => m.杯号 === c));
  const 危险度 = 未知危险度(s);
  const 毒池上界 = 毒池区间(s)[1];
  const 抽 = (池: number[]): number => 池[Math.floor(rng() * 池.length)];
  const 加冰杯 = 剩.filter(c => 对局.冰杯.includes(c));
  const 啤酒可选 = 剩.filter(c => 对局.啤酒杯.includes(c) && !对局.冰杯.includes(c));
  const 安全无冰 = 已知安全.filter(c => !对局.冰杯.includes(c));
  const 安全带冰 = 已知安全.filter(c => 对局.冰杯.includes(c));   // 她做过的求生冰：喝下不涨醉意
  const 毒无冰 = 已知毒.filter(c => !对局.冰杯.includes(c));
  const 毒带冰 = 已知毒.filter(c => 对局.冰杯.includes(c));
  // 推理收紧：她看穿的毒杯数盖住毒池上界（最坏情况也全被她看穿），才敢认定未知杯全安全
  const 安全池 = [...已知安全, ...(已知毒.length >= 毒池上界 ? 未知 : [])];
  const 醉满 = 对局.梵醺儿醉意 >= 上限;   // 再喝普通酒就判负

  // ── 平时：确定安全的优先，赌有底线 ──
  if (!醉满) {
    // 啤酒安全解馋（+2），醉意装得下就先喝
    if (对局.梵醺儿醉意 <= 上限 - 2 && 啤酒可选.length > 0) return 抽(啤酒可选);
    if (安全无冰.length > 0) return 抽(安全无冰);
    if (安全带冰.length > 0) return 抽(安全带冰);
    // 冒险档：赌未知杯。血越薄、毒越浓、杯上还有冰（毒＋冰＝扣两命），越不该赌
    const 赌池 = 对局.梵醺儿生命 <= 2 ? 未知.filter(c => !对局.冰杯.includes(c)) : 未知;
    const 敢赌 = 对局.梵醺儿生命 > 2 ? true : 对局.梵醺儿生命 === 2 ? 危险度 < 0.5 : 危险度 <= 0;
    if (赌池.length > 0 && 敢赌) return 抽(赌池);
    if (安全池.length > 0) return 抽(安全池);
    if (赌池.length > 0) return 抽(赌池); // 没有已知安全，被迫赌
    // 血厚时的冒险：明知是毒也喝，用一条命换桌上的进度
    if (对局.梵醺儿生命 > 1 && 毒无冰.length > 0) return 抽(毒无冰);
    if (剩.length > 0) return 抽(剩);
    return null;
  }

  // ── 醉满：喝普通酒等于认输，只找"不涨醉意"的活路 ──
  // 1) 加过冰的非毒杯（她做过的求生冰、加冰的啤酒）：喝下醉意不动，零损失
  const 冰非毒 = 加冰杯.filter(c => 对局.啤酒杯.includes(c) || 已知安全.includes(c));
  if (冰非毒.length > 0) return 抽(冰非毒);
  // 2) 没加冰的已知毒杯：必然活命的毒（扣一命）
  if (对局.梵醺儿生命 > 1 && 毒无冰.length > 0) return 抽(毒无冰);
  // 3) 赌未知杯：醉满时毒是活路——赌它"是毒"；加过冰的未知赌的是"它是普通"。
  //    只在胜率过半时下手（毒浓赌无冰的，毒稀赌带冰的），胜率不过半就走下面的保命路
  const 赌冰 = 加冰杯.filter(c => !已知毒.includes(c));
  const 赌无冰 = 未知.filter(c => !对局.冰杯.includes(c));
  if (危险度 >= 0.5 && 赌无冰.length > 0) return 抽(赌无冰);
  if (危险度 <= 0.5 && 赌冰.length > 0) return 抽(赌冰);
  // 4) 加了冰的已知毒杯：扣两命活命（血要厚）
  if (对局.梵醺儿生命 > 2 && 毒带冰.length > 0) return 抽(毒带冰);
  if (对局.梵醺儿生命 > 1 && 毒带冰.length > 0) return 抽(毒带冰);
  // 5) 走投无路：没有稳的、胜率也不过半——赌一把未知仍好过喝明知是普通的
  if (赌无冰.length > 0) return 抽(赌无冰);
  return 抽(剩);
}

/** 她的回合·阶段二（叙述楼层二）：先判劝酒（达令被迫喝下她指定的杯，可用解酒药抵消护身；
 *  不计入达令已喝杯数），再她自己喝主杯。之后回到达令的回合。 */
function 结算她喝酒阶段(s: StatData, rng: Rng): string {
  const 对局 = s.对局;
  对局.她的阶段 = '喝酒';
  // 对称规则：她自己也必须先喝过一杯，才有资格劝酒——她先喝主杯，喝完再决定劝不劝
  const 喝的结果 = 她喝主杯(s, rng, false);
  if (对局.状态 !== '对局中' || 对局.行动方 !== '梵·醺儿') {
    // 已终局或已换轮交回玩家：喝的阶段直接收尾
    return 喝的结果;
  }
  const 劝 = 她劝酒选杯(s, rng);
  if (劝 !== null) {
    // 递杯待回应：不立刻结算，等达令选择喝下或用强行换杯换掉再喝
    对局.她已劝酒 = true;
    对局.她劝的杯号 = 劝;
    对局.她的阶段 = '劝酒';
    对局.上轮结果 = `她回合：${喝的结果.replace('她回合：', '')}，她把第${劝}杯递到达令唇边`;
    return `她已喝下自己的一杯，又把第${劝}杯递到达令唇边，等达令回应`;
  }
  // 不劝：收尾控杯（毒药/啤酒还能再摆一次桌面）后交回达令
  const 控 = 她控杯(s, rng);
  if (对局.状态 !== '对局中') {
    对局.上轮结果 = 喝的结果 + (控.length ? `，${控.join('，')}` : '');
    return 对局.上轮结果;
  }
  if (本轮毒酒已尽(s) || 对局.剩余杯数 <= 0) {
    const 接 = 换轮并接管(s, rng);
    if (接) return 接;
    if (对局.状态 === '对局中') { 对局.行动方 = '玩家'; 对局.她的阶段 = '道具'; }
    对局.上轮结果 = 喝的结果 + (控.length ? `，${控.join('，')}` : '');
    return 对局.上轮结果;
  }
  if (对局.状态 === '对局中') { 对局.行动方 = '玩家'; 对局.她的阶段 = '道具'; }
  对局.上轮结果 = 喝的结果 + (控.length ? `，${控.join('，')}` : '');
  return 对局.上轮结果;
}

/** 她喝主杯并收尾；若还有劝酒环节则先不交回合（由调用方决定） */
function 她喝主杯(s: StatData, rng: Rng, 允许交回: boolean): string {
  const 对局 = s.对局;
  const 记录: string[] = [];
  const 落账 = (): string => {
    对局.上轮结果 = `她回合：${记录.join('，')}`;
    return 对局.上轮结果;
  };
  const c = 她选杯(s, rng);
  if (c !== null) {
    const 饮 = 喝酒(s, '梵·醺儿', c, rng);
    记录.push(饮 ?? `她喝下第${c}杯`);
    if (对局.状态 !== '对局中') return 落账();
    // 连喝决策：第一杯落肚后还活着、醉意装得下第二杯，才谈冒险——绝不让连喝变成送头
    if (对局.梵醺儿生命 > 1 && 对局.梵醺儿醉意 + 1 <= (对局.梵醺儿醉意上限 ?? 6) && 她想连喝(s, rng)) {
      const c2 = 她选杯(s, rng);
      if (c2 !== null) {
        const 饮2 = 喝酒(s, '梵·醺儿', c2, rng);
        记录.push(饮2 ?? `她喝下第${c2}杯`);
        if (对局.状态 !== '对局中') return 落账();
      }
    }
  }
  if (本轮毒酒已尽(s) || 对局.剩余杯数 <= 0) {
    const 接 = 换轮并接管(s, rng);
    if (接) return 接;
    if (对局.状态 === '对局中') { 对局.行动方 = '玩家'; 对局.她的阶段 = '道具'; }
    return 落账();
  }
  // 未毒尽未杯尽：劝酒判定前不交回（保持她的行动权，等调用方决定）
  if (允许交回) { 对局.行动方 = '玩家'; 对局.她的阶段 = '道具'; }
  return 落账();
}

/** 劝酒回应：换杯目标为 null 直接喝；否则先把她的杯与目标杯交换再喝（换到什么喝什么）。她已喝过主杯，回应后收尾交回。 */
function 结算劝酒回应(s: StatData, 换杯目标: number | null, rng: Rng): string {
  const 对局 = s.对局;
  const 劝杯 = 对局.她劝的杯号;
  const 记录: string[] = [];
  if (换杯目标 !== null) {
    对局.道具背包.玩家['强行换杯'] -= 1;
    交换杯位(对局, 劝杯, 换杯目标);
    记录.push(`达令用强行换杯把第${劝杯}杯与第${换杯目标}杯交换`);
  }
  const 轮前 = 对局.轮数;
  const 饮 = 喝酒(s, '玩家', 劝杯, rng);
  对局.她劝的杯号 = 0;
  记录.push(`她劝酒：${饮 ?? `达令喝下第${劝杯}杯`}`);
  if (对局.状态 !== '对局中') {
    对局.上轮结果 = `她回合：${记录.join('，')}`;
    return 对局.上轮结果;
  }
  记录.push(...她控杯(s, rng)); // 回合收尾控杯：毒药/啤酒还能再摆一次桌面
  if (对局.状态 !== '对局中') {
    对局.上轮结果 = `她回合：${记录.join('，')}`;
    return 对局.上轮结果;
  }
  if (对局.轮数 !== 轮前 || 本轮毒酒已尽(s) || 对局.剩余杯数 <= 0) {
    const 接 = 对局.轮数 === 轮前 ? 换轮并接管(s, rng) : '';
    if (接) return 接;
    if (对局.状态 === '对局中') { 对局.行动方 = '玩家'; 对局.她的阶段 = '道具'; }
    对局.上轮结果 = `她回合：${记录.join('，')}`;
    return 对局.上轮结果;
  }
  if (对局.状态 === '对局中') { 对局.行动方 = '玩家'; 对局.她的阶段 = '道具'; }
  对局.上轮结果 = `她回合：${记录.join('，')}`;
  return 对局.上轮结果;
}

function 她控杯(s: StatData, rng: Rng): string[] {
  const 对局 = s.对局;
  const 包 = 对局.道具背包['梵·醺儿'];
  const 记录: string[] = [];
  const 未饮 = 未饮杯号(s);
  const 剩余毒数 = Math.max(0, 对局.本轮毒酒数 - 对局.已揭晓.filter(x => x.毒性 === '毒酒').length);
  // 投毒压桌：达令剩一血时果断，平时毒液稀薄时加密（她残血时不敢投——怕自己喝到）
  if (包['毒药'] > 0 && 未饮.length > 0 && 对局.梵醺儿生命 > 1) {
    const 该投 = 对局.玩家生命 === 1 ? rng() < 0.5 : 剩余毒数 / 未饮.length < 0.3 && rng() < 0.25;
    if (该投) {
      包['毒药'] -= 1;
      const 详 = 应用她道具(s, '毒药', rng);
      记录.push(`毒药使用${详 ? `（${详}）` : ''}`);
    }
  }
  // 换啤酒埋杀/排雷：达令醉到边上时，桌上多一杯公开啤酒就是递到嘴边的刀
  if (包['啤酒'] > 0 && 对局.梵醺儿醉意 <= 4 && rng() < 0.5) {
    const 可换 = 未饮杯号(s).filter(c => !对局.啤酒杯.includes(c));
    if (可换.length > 0) {
      包['啤酒'] -= 1;
      const 详 = 应用她道具(s, '啤酒', rng);
      if (详) 记录.push(`啤酒使用（${详}）`);
      else 包['啤酒'] += 1; // 没换成不消耗
    }
  }
  return 记录;
}

function 未饮杯号(s: StatData): number[] {
  return Array.from({ length: s.对局.本轮总杯数 }, (_v, i) => i + 1).filter(x => !s.对局.已揭晓.some(item => item.杯号 === x));
}

/** 应用她的道具，返回供"上轮结果"记录的明细；不写公共透视图（她的情报不向玩家泄露）。
 *  红冰求生=true 时冰放进她看穿的普通杯（自己喝不涨醉意），否则放进看穿的毒杯（加重毒性）。 */
function 应用她道具(s: StatData, k: 道具名, rng: Rng, 红冰求生 = false): string {
  const 对局 = s.对局;
  let 详 = '';
  if (k === '解酒药') {
    if (对局.梵醺儿生命 < 对局.生命上限) { 对局.梵醺儿生命 += 1; 详 = '生命+1'; }
  } else if (k === '透视酒杯') {
    const 未知杯 = 未饮杯号(s).filter(c => !对局.$她透视.some(m => m.杯号 === c));
    if (未知杯.length > 0) {
      const c = 未知杯[Math.floor(rng() * 未知杯.length)];
      对局.$她透视.push({ 杯号: c, 毒性: 对局.$序列[c - 1] }); // 记进她的私人备忘录，跨回合保留
      详 = `她看穿了第${c}杯`;
    }
  } else if (k === '强行换杯') {
    const 剩 = 未饮杯号(s);
    if (剩.length >= 2) {
      // 首选打达令唯一的情报杯：把她看穿的毒杯换到达令透视的"安全杯"位置——
      // 情报跟着杯走（她依旧掌握毒杯去向），但达令那杯从此是毒杯，只能弃掉重赌
      const 达令杯 = 对局.$透视图?.杯号 && 对局.$透视图.毒性 === '普通' && 剩.includes(对局.$透视图.杯号) ? 对局.$透视图.杯号 : 0;
      const 毒杯 = 对局.$她透视.filter(m => m.毒性 === '毒酒' && 剩.includes(m.杯号) && m.杯号 !== 达令杯).map(m => m.杯号);
      if (达令杯 && 毒杯.length > 0) {
        const 毒 = 毒杯[Math.floor(rng() * 毒杯.length)];
        交换杯位(对局, 达令杯, 毒);
        详 = `把第${毒}杯与第${达令杯}杯换了位置`;
      } else {
        // 没有可打的目标就不空换：随手调换两只未知杯，至少打乱达令数好的节奏
        const a = 剩[Math.floor(rng() * 剩.length)];
        const b = 剩[Math.floor(rng() * 剩.length)];
        const 甲 = a; const 乙 = b === a ? 剩[(剩.indexOf(b) + 1) % 剩.length] : b;
        交换杯位(对局, 甲, 乙);
        详 = `第${甲}杯与第${乙}杯互换位置`;
      }
    }
  } else if (k === '啤酒') {
    // 把一杯换成啤酒（桌上公开），不当场喝：优先换她没有情报的未知杯——顺手排掉一个不确定
    const 已知杯 = 对局.$她透视.filter(m => 未饮杯号(s).includes(m.杯号)).map(m => m.杯号);
    const 未饮 = 未饮杯号(s).filter(c => !对局.啤酒杯.includes(c));
    const 未知池 = 未饮.filter(c => !已知杯.includes(c));
    const 池 = 未知池.length > 0 ? 未知池 : 未饮;
    if (池.length > 0) {
      const c = 池[Math.floor(rng() * 池.length)];
      if (对局.$序列[c - 1] === '毒酒') 对局.本轮毒酒数 -= 1; // 倒掉的若是毒酒，计数同步扣减
      对局.$序列[c - 1] = '普通';
      if (对局.$透视图?.杯号 === c) 对局.$透视图 = null;
      她忘杯(对局, c);
      对局.啤酒杯.push(c);
      对局.本轮换酒数 += 1;
      详 = `把第${c}杯换成了啤酒`;
    }
  } else if (k === '薄荷') {
    对局.梵醺儿醉意 = Math.max(0, 对局.梵醺儿醉意 - 2);
  } else if (k === '毒药') {
    const 剩 = 未饮杯号(s).filter(c => !对局.啤酒杯.includes(c));
    if (剩.length > 0) {
      const c = 剩[Math.floor(rng() * 剩.length)];
      if (对局.$序列[c - 1] !== '毒酒') {
        对局.$序列[c - 1] = '毒酒';
        对局.本轮毒酒数 += 1;
        if (对局.$透视图?.杯号 === c) 对局.$透视图.毒性 = '毒酒';
      }
      对局.本轮投毒数 += 1;
      详 = '毒液混入了一杯酒';
    }
  } else if (k === '红冰') {
    // 放冰只认她看穿的杯：求生放普通杯（回头自己喝，不涨醉意），进攻放毒杯（喝下多扣一条命）；
    // 绝不放进未知杯——那等于送达令一杯不涨醉意的安全酒
    const 未饮 = 未饮杯号(s).filter(c => !对局.冰杯.includes(c));
    const 毒情报杯 = 对局.$她透视.filter(m => m.毒性 === '毒酒' && 未饮.includes(m.杯号)).map(m => m.杯号);
    const 普通情报杯 = 对局.$她透视.filter(m => m.毒性 === '普通' && 未饮.includes(m.杯号)).map(m => m.杯号);
    const 池 = 红冰求生 ? (普通情报杯.length > 0 ? 普通情报杯 : 毒情报杯) : (毒情报杯.length > 0 ? 毒情报杯 : 普通情报杯);
    if (池.length > 0) {
      const c = 池[Math.floor(rng() * 池.length)];
      对局.冰杯.push(c);
      详 = `把红冰放入了第${c}杯`;
    }
  }
  醉倒(s);
  return 详;
}

function 使用解酒药(s: StatData): { changed: boolean; 描述: string } {
  const 对局 = s.对局;
  if (对局.行动方 !== '玩家' || 对局.道具背包.玩家['解酒药'] <= 0) return { changed: false, 描述: '' };
  if (对局.玩家生命 >= 对局.生命上限) return { changed: false, 描述: '' }; // 只能回血，满血时用不了
  对局.道具背包.玩家['解酒药'] -= 1;
  对局.玩家生命 += 1;
  return { changed: true, 描述: '达令使用解酒药，生命+1' };
}
function 使用透视(s: StatData, 杯号: number): { changed: boolean; 描述: string } {
  const 对局 = s.对局;
  if (对局.行动方 !== '玩家' || 对局.道具背包.玩家['透视酒杯'] <= 0) return { changed: false, 描述: '' };
  if (对局.已揭晓.some(x => x.杯号 === 杯号)) return { changed: false, 描述: '' };
  if (对局.$透视图?.杯号 === 杯号) return { changed: false, 描述: '' }; // 已看过同一杯，不浪费道具
  const 毒性 = 对局.$序列[杯号 - 1]; if (毒性 === undefined) return { changed: false, 描述: '' };
  对局.道具背包.玩家['透视酒杯'] -= 1; 对局.$透视图 = { 杯号, 毒性 };
  return { changed: true, 描述: `达令使用透视酒杯，看到第${杯号}杯是${毒性 === '毒酒' ? '毒酒' : '普通酒'}` };
}
function 使用换杯(s: StatData, 甲号: number, 乙号: number): { changed: boolean; 描述: string } {
  const 对局 = s.对局;
  if (对局.行动方 !== '玩家' || 对局.道具背包.玩家['强行换杯'] <= 0 || 甲号 === 乙号) return { changed: false, 描述: '' };
  if (对局.已揭晓.some(x => x.杯号 === 甲号) || 对局.已揭晓.some(x => x.杯号 === 乙号)) return { changed: false, 描述: '' };
  const 甲 = 对局.$序列[甲号 - 1]; const 乙 = 对局.$序列[乙号 - 1]; if (甲 === undefined || 乙 === undefined) return { changed: false, 描述: '' };
  对局.道具背包.玩家['强行换杯'] -= 1; 交换杯位(对局, 甲号, 乙号); // 交换是公开动作，双方情报跟着换位
  // 杯内容换位后，透视结果跟着换，不能让玩家拿旧情报决策
  if (对局.$透视图?.杯号 === 甲号) 对局.$透视图.毒性 = 对局.$序列[甲号 - 1];
  else if (对局.$透视图?.杯号 === 乙号) 对局.$透视图.毒性 = 对局.$序列[乙号 - 1];
  return { changed: true, 描述: `达令使用强行换杯，交换了第${甲号}杯和第${乙号}杯的位置` };
}
function 使用啤酒(s: StatData, 杯号: number, rng: Rng): { changed: boolean; 描述: string } {
  const 对局 = s.对局;
  if (对局.行动方 !== '玩家' || 对局.道具背包.玩家['啤酒'] <= 0) return { changed: false, 描述: '' };
  if (!Number.isInteger(杯号) || 杯号 < 1 || 杯号 > 对局.本轮总杯数) return { changed: false, 描述: '' };
  if (对局.已揭晓.some(x => x.杯号 === 杯号)) return { changed: false, 描述: '' };
  if (对局.啤酒杯.includes(杯号)) return { changed: false, 描述: '' }; // 这杯已经是啤酒
  对局.道具背包.玩家['啤酒'] -= 1;
  if (对局.$序列[杯号 - 1] === '毒酒') 对局.本轮毒酒数 -= 1; // 毒酒被倒掉换酒，计数同步扣减
  对局.$序列[杯号 - 1] = '普通';
  if (对局.$透视图?.杯号 === 杯号) 对局.$透视图 = null;
  她忘杯(对局, 杯号); // 换酒是公开动作，这杯的旧情报作废
  对局.本轮换酒数 += 1;
  对局.啤酒杯.push(杯号); // 桌上公开的啤酒：之后自己喝或劝她喝，谁喝都是醉意+2、绝对安全
  // 不揭晓原来是什么酒：毒池区间随推演移动（换的杯可能原是毒）
  const 池 = 毒池区间(s);
  let 描述 = `达令把第${杯号}杯换成了啤酒（桌上公开）——毒池现在可能在 ${池[0]}~${池[1]} 杯，喝或劝随你`;
  if (对局.状态 !== '对局中') return { changed: true, 描述 };
  // 换掉的可能是毒：毒尽时正常结算换轮（新轮先手按奇偶交替）
  if (本轮毒酒已尽(s)) 描述 += 换轮并接管(s, rng);
  return { changed: true, 描述 };
}
function 使用薄荷(s: StatData): { changed: boolean; 描述: string } {
  const 对局 = s.对局;
  if (对局.行动方 !== '玩家' || 对局.道具背包.玩家['薄荷'] <= 0 || 对局.玩家醉意 <= 0) return { changed: false, 描述: '' };
  对局.道具背包.玩家['薄荷'] -= 1; 对局.玩家醉意 = Math.max(0, 对局.玩家醉意 - 2);
  return { changed: true, 描述: '达令使用薄荷，醉意-2' };
}
function 使用毒药(s: StatData, rng: Rng): { changed: boolean; 描述: string } {
  const 对局 = s.对局;
  if (对局.行动方 !== '玩家' || 对局.道具背包.玩家['毒药'] <= 0) return { changed: false, 描述: '' };
  // 落点是任意未饮非啤酒杯（啤酒绝对安全不可污染）：可能撞上已有的毒白投——投毒后毒池只能推演区间
  const 剩 = 未饮杯号(s).filter(c => !对局.啤酒杯.includes(c));
  if (剩.length === 0) return { changed: false, 描述: '' };
  对局.道具背包.玩家['毒药'] -= 1;
  const c = 剩[Math.floor(rng() * 剩.length)];
  if (对局.$序列[c - 1] !== '毒酒') {
    对局.$序列[c - 1] = '毒酒';
    对局.本轮毒酒数 += 1;
    if (对局.$透视图?.杯号 === c) 对局.$透视图.毒性 = '毒酒';
  }
  对局.本轮投毒数 += 1;
  // 落点随机且不指名——连投毒者自己也不知道混进了哪一杯，叙述不得点名
  const 池 = 毒池区间(s);
  return { changed: true, 描述: `达令使用毒药，把毒液悄悄混入桌上的一杯酒——毒池可能在 ${池[0]}~${池[1]} 杯` };
}
function 使用红冰(s: StatData, 杯号: number): { changed: boolean; 描述: string } {
  const 对局 = s.对局;
  if (对局.行动方 !== '玩家' || 对局.道具背包.玩家['红冰'] <= 0) return { changed: false, 描述: '' };
  if (!Number.isInteger(杯号) || 杯号 < 1 || 杯号 > 对局.本轮总杯数) return { changed: false, 描述: '' };
  if (对局.已揭晓.some(x => x.杯号 === 杯号)) return { changed: false, 描述: '' };
  if (对局.冰杯.includes(杯号)) return { changed: false, 描述: '' }; // 这杯已有冰
  对局.道具背包.玩家['红冰'] -= 1;
  对局.冰杯.push(杯号);
  return { changed: true, 描述: `达令把红冰放入第${杯号}杯（桌上公开：这杯若是毒酒，喝下额外多扣一点生命；若是其他酒，喝下不涨醉意）` };
}
