import { defineMvuDataStore } from '@util/mvu';
import { 容错Schema } from '../../schema';

/**
 * 状态栏+对局桌面数据源：按楼层快照读取 stat_data。
 * 引擎把新状态写入新生成的玩家消息与 AI 回复楼层；当前楼层保持旧快照，
 * 直到 AI 回复的新楼层出现才更新前端（即"进入新回复再更新"）。
 * 用容错 Schema：AI 的 UpdateVariable 写坏楼层数据时丢弃脏条目回默认值，
 * 页面不崩，且 2 秒轮询会把清洗后的数据写回该楼层（自愈）。
 */
export const useDataStore = defineMvuDataStore(容错Schema, { type: 'message', message_id: getCurrentMessageId() });
