export const Schema = z.object({
    灵魂: z.object({
        占有度: z.coerce.number().transform(v => _.clamp(v, 0, 100)),
        情绪: z.enum(['低迷', '痴迷', '狂暴']),
        行为: z.string(),
        奖励次数: z.coerce.number(),
    }),
    对局: z.object({
        状态: z.enum(['未开始', '对局中', '结算', '终局']),
        档位: z.enum(['轻简', '普通', '狂欢', '深度']),
        轮数: z.coerce.number(),
        行动方: z.enum(['玩家', '梵·醺儿']),
        玩家生命: z.coerce.number(),
        梵醺儿生命: z.coerce.number(),
        生命上限: z.coerce.number(),
        玩家醉意: z.coerce.number(),
        梵醺儿醉意: z.coerce.number(),
        本轮总杯数: z.coerce.number(),
        本轮毒酒数: z.coerce.number(),
        本轮开局毒数: z.coerce.number(),
        本轮补道具数: z.coerce.number(),
        剩余杯数: z.coerce.number(),
        结果: z.enum(['未定', '玩家胜', '梵醺儿胜']),
        已揭晓: z.array(z.object({
            杯号: z.coerce.number(),
            毒性: z.enum(['普通', '毒酒']),
            饮者: z.enum(['玩家', '梵·醺儿']),
        })),
        道具背包: z.object({
            玩家: z.record(z.enum(['解酒药', '透视酒杯', '强行换杯', '啤酒', '薄荷', '毒药', '红冰']), z.coerce.number()),
            '梵·醺儿': z.record(z.enum(['解酒药', '透视酒杯', '强行换杯', '啤酒', '薄荷', '毒药', '红冰']), z.coerce.number()),
        }),
        上轮结果: z.string(),
        本轮结果: z.string(),
        已喝杯数: z.coerce.number(),
        已劝酒: z.coerce.boolean(),
        她的阶段: z.enum(['道具', '喝酒', '劝酒']),
        她已劝酒: z.coerce.boolean(),
        她劝的杯号: z.coerce.number(),
        啤酒杯: z.array(z.coerce.number()),
        冰杯: z.array(z.coerce.number()),
        本轮投毒数: z.coerce.number(),
        本轮换酒数: z.coerce.number(),
        上次饮酒: z.string(),
        玩家醉意上限: z.coerce.number(),
        梵醺儿醉意上限: z.coerce.number(),
    }),
});
const 数 = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : undefined;
};
const 枚举或 = (v, 允许, 缺省) => 允许.includes(v) ? v : 缺省;
/**
 * 页面容错清洗：AI 的 UpdateVariable 可能往 stat_data 写入残缺数据
 * （如 已揭晓 里 insert 出 {杯号: null}），util/mvu 初次解析用会抛错的 parse，
 * 一层脏数据会让整个楼层页面初始化崩溃。这里在解析前把已知的脏形态修掉：
 * 无效的已揭晓条目直接丢弃、数字/枚举回默认值。只用于前端 store，
 * 注册与 dump 仍用原 Schema。
 */
function 清理(input) {
    if (!_.isPlainObject(input))
        return input;
    const 对局原 = _.isPlainObject(input.对局) ? input.对局 : {};
    const 已揭晓 = Array.isArray(对局原.已揭晓)
        ? 对局原.已揭晓.flatMap(item => {
            if (!_.isPlainObject(item))
                return [];
            const 杯号 = 数(item.杯号);
            if (杯号 === undefined || !Number.isInteger(杯号) || 杯号 < 1)
                return [];
            const 毒性 = item.毒性;
            const 饮者 = item.饮者;
            return [{ 杯号, 毒性: 毒性 === '毒酒' ? '毒酒' : '普通', 饮者: 饮者 === '梵·醺儿' ? '梵·醺儿' : '玩家' }];
        })
        : [];
    const 清背包 = (v) => {
        const src = _.isPlainObject(v) ? v : {};
        const out = { 解酒药: 0, 透视酒杯: 0, 强行换杯: 0, 啤酒: 0, 薄荷: 0, 毒药: 0, 红冰: 0 };
        for (const key of Object.keys(out)) {
            const n = 数(src[key]);
            if (n !== undefined)
                out[key] = n;
        }
        return out;
    };
    const 背包原 = _.isPlainObject(对局原.道具背包) ? 对局原.道具背包 : {};
    const 对局 = {
        ...对局原,
        状态: 枚举或(对局原.状态, ['未开始', '对局中', '结算', '终局'], '未开始'),
        档位: 枚举或(对局原.档位, ['轻简', '普通', '狂欢', '深度'], '普通'),
        轮数: 数(对局原.轮数) ?? 0,
        行动方: 枚举或(对局原.行动方, ['玩家', '梵·醺儿'], '玩家'),
        玩家生命: 数(对局原.玩家生命) ?? 0,
        梵醺儿生命: 数(对局原.梵醺儿生命) ?? 0,
        生命上限: 数(对局原.生命上限) ?? 3,
        玩家醉意: 数(对局原.玩家醉意) ?? 0,
        梵醺儿醉意: 数(对局原.梵醺儿醉意) ?? 0,
        本轮总杯数: 数(对局原.本轮总杯数) ?? 0,
        本轮毒酒数: 数(对局原.本轮毒酒数) ?? 0,
        本轮开局毒数: 数(对局原.本轮开局毒数) ?? 0,
        本轮补道具数: 数(对局原.本轮补道具数) ?? 0,
        剩余杯数: 数(对局原.剩余杯数) ?? 0,
        结果: 枚举或(对局原.结果, ['未定', '玩家胜', '梵醺儿胜'], '未定'),
        已揭晓,
        道具背包: { 玩家: 清背包(背包原.玩家), '梵·醺儿': 清背包(背包原['梵·醺儿']) },
        上轮结果: typeof 对局原.上轮结果 === 'string' ? 对局原.上轮结果 : '',
        本轮结果: typeof 对局原.本轮结果 === 'string' ? 对局原.本轮结果 : '',
        已喝杯数: 数(对局原.已喝杯数) ?? 0,
        已劝酒: 对局原.已劝酒 === true,
        她的阶段: 枚举或(对局原.她的阶段, ['道具', '喝酒', '劝酒'], '道具'),
        她已劝酒: 对局原.她已劝酒 === true,
        她劝的杯号: 数(对局原.她劝的杯号) ?? 0,
        啤酒杯: Array.isArray(对局原.啤酒杯)
            ? [...new Set(对局原.啤酒杯.filter(v => { const n = Number(v); return Number.isInteger(n) && n >= 1; }))]
            : [],
        冰杯: Array.isArray(对局原.冰杯)
            ? [...new Set(对局原.冰杯.filter(v => { const n = Number(v); return Number.isInteger(n) && n >= 1; }))]
            : [],
        本轮投毒数: 数(对局原.本轮投毒数) ?? 0,
        本轮换酒数: 数(对局原.本轮换酒数) ?? 0,
        上次饮酒: typeof 对局原.上次饮酒 === 'string' ? 对局原.上次饮酒 : '',
        玩家醉意上限: 数(对局原.玩家醉意上限) ?? 6,
        梵醺儿醉意上限: 数(对局原.梵醺儿醉意上限) ?? 6,
    };
    const 灵魂原 = _.isPlainObject(input.灵魂) ? input.灵魂 : {};
    const 灵魂 = {
        ...灵魂原,
        占有度: 数(灵魂原.占有度) ?? 0,
        情绪: 枚举或(灵魂原.情绪, ['低迷', '痴迷', '狂暴'], '痴迷'),
        行为: typeof 灵魂原.行为 === 'string' ? 灵魂原.行为 : '',
        奖励次数: 数(灵魂原.奖励次数) ?? 0,
    };
    return { ...input, 灵魂, 对局 };
}
/** 前端 store 用：解析前先清洗，AI 写坏的楼层数据不再让页面崩溃 */
export const 容错Schema = z.preprocess(清理, Schema);
